/**
 * Validator fixtures: every forbidden construct, with the rule it breaks, the
 * text where the error must point, and a valid twin that must pass, so the
 * validator can never drift into being over-strict unnoticed.
 */

export interface Fragments {
  readonly html: string;
  readonly css: string;
  readonly js: string;
}

export interface ValidatorCase {
  readonly name: string;
  readonly fragment: 'html' | 'css' | 'js';
  readonly rule: string;
  /** Overrides on top of the base scene. */
  readonly bad: Partial<Fragments>;
  /** Where the error points: the first occurrence of this text in the fragment, or an offset. */
  readonly at: string | number;
  readonly twin: Partial<Fragments>;
}

export const BASE_HTML = "<div id='stage'></div>";
export const BASE_JS = [
  "const stage = inc.svg('#stage', { viewBox: [0, 0, 100, 100], title: 'Dot' });",
  "const dot = stage.circle(50, 50, 4, { tone: 'lit' });",
].join('\n');

export function scene(overrides: Partial<Fragments> = {}): Fragments {
  return { html: BASE_HTML, css: '', js: BASE_JS, ...overrides };
}

const js = (...lines: string[]) => `${BASE_JS}\n${lines.join('\n')}`;

